export function productTierView(data,quantity,{decorationMandatory=false}={}){
 if(!data?.available||!data.tiers?.length)return `<p class="small muted">${e(data?.message||'Varepriserne kunne ikke indlæses.')}</p>`;
 const money=value=>new Intl.NumberFormat('da-DK',{style:'currency',currency:'DKK'}).format(value/100),tiers=data.tiers,first=tiers[0];
 return `<div class="pf-quantity-head"><strong>Mængderabat</strong><span>Pr. stk. ${vatLabel()} · ${decorationMandatory?'før tryk':'uden tryk'}</span></div><div class="pf-quantity-tiers">${tiers.map((row,index)=>{const next=tiers[index+1],selected=quantity>=row.min&&(!next||quantity<next.min),saving=first.unitIncVat>row.unitIncVat?Math.round((1-row.unitIncVat/first.unitIncVat)*1000)/10:0;return `<button type="button" data-tier-quantity="${row.min}" class="pf-quantity-tier${selected?' selected':''}" aria-pressed="${selected}"><span>${row.min}+ stk.</span><strong>${money(fromInc(row.unitIncVat,row.unitExVat))}</strong><small>${saving?`Spar ${new Intl.NumberFormat('da-DK',{maximumFractionDigits:1}).format(saving)} %`:'Vælg antal'}</small></button>`;}).join('')}</div>${decorationMandatory?'<p class="small muted">Dette produkt kræver dekoration. Trykprisen kommer oveni.</p>':'<p class="small muted">Lagervarer kan bestilles med logo fra 1 stk. Specialproduktion aftales særskilt.</p>'}`;
}
