 async function uploadLogos(files){files=[...files].filter(Boolean);if(!files.length)return;checkpoint();const version=++uploadVersion;uploading=true;$('add-cart').disabled=true;try{for(const file of files){let stored=await saveFile(file);stored={...stored,pantone:await readArtworkPantone(file)};if(version!==uploadVersion)return;let displayFile=await createVectorPreview(file);if(displayFile){const analysis=await inspectLogoPalette(displayFile);if(analysis?.count)stored={...stored,detectedColors:analysis.count,detectedPalette:analysis.colors.map(row=>({hex:row.hex,share:row.share}))};if(analysis?.count)stored={...stored,recolorable:await previewHasTransparency(displayFile).catch(()=>false)};const image=await createImageBitmap(displayFile);const dimensions=[image.width,image.height];image.close?.();if(displayFile!==file){const previewStored=await saveFile(displayFile,{preview:true});stored={...stored,previewId:previewStored.id,previewType:previewStored.type};}stored={...stored,pixelWidth:dimensions[0],pixelHeight:dimensions[1]};}const art=normalizeArtworkForOption({id:crypto.randomUUID?.()||`art-${Date.now()}-${Math.random()}`,logo:stored,x:.5,y:.5,scale:.34},option);artworks.push(art);activeArtworkId=art.id;}logo=artworks[0]?.logo||null;$('upload-modal').hidden=true;await preview();}catch(error){$('upload-error').textContent=error.message;notify(error.message);}finally{if(version===uploadVersion){uploading=false;renderApproval();schedulePrice();}}}
